// Governance check: standards-page-contract.md (example imagery). Every example on a
// `/standards/*` page uses the shared fixtures in src/data/examples: local images from
// src/assets/examples, clips through mediaUrl(), dates computed from today, and a snippet
// generated by buildExampleSnippet() from the same props the page renders.
// Hotlinked stock/placeholder hosts and hand-typed snippet strings fail the build.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const dirs = ["src/pages/standards", "src/pages/examples", "src/data"].map((d) => path.join(root, d));
if (!fs.existsSync(dirs[0])) {
  console.log("check-standards-examples: no src/pages/standards directory, skipping.");
  process.exit(0);
}

// Pages whose snippet stays hand-written by design: payment/embed providers and the print-tool link pages, where the
// snippet shows placeholder ids or config rather than the rendered widget. Everything else must generate its snippet.
const HAND_WRITTEN_SNIPPET_OK = new Set([
  "PayPalButtonsStandardPage.tsx", "PayPalButtonsDonateStandardPage.tsx",
  "PayPalButtonsHostedStandardPage.tsx", "ZeffyDonatePatternPage.tsx", "GivebutterPatternPage.tsx",
  "FormEmbedModalStandardPage.tsx", "SocialPostEmbedStandardPage.tsx", "PlaceholderStandardPage.tsx",
  "KennelDisplayToolsStandardPage.tsx",
  "DocumentsStandardPage.tsx", "FlyerBuilderStandardPage.tsx",
]);

const BANNED_HOSTS = /images\.unsplash\.com|placehold\.co|www\.4leggedit\.com\/assets|interactive-examples\.mdn\.mozilla\.net|commondatastorage\.googleapis\.com|chewy\.com/i;
const HARD_DATE = /["'`]20\d{2}-\d{2}-\d{2}["'`]/;
const failures = [];

const walk = (dir) =>
  fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) =>
    e.isDirectory() ? walk(path.join(dir, e.name)) : /\.(ts|tsx)$/.test(e.name) && !/\.test\./.test(e.name) ? [path.join(dir, e.name)] : [],
  );

for (const dir of dirs.filter(fs.existsSync)) {
  for (const file of walk(dir)) {
    const rel = path.relative(root, file);
    const name = path.basename(file);
    const source = fs.readFileSync(file, "utf8");
    if (BANNED_HOSTS.test(source)) failures.push(`${rel}: hotlinked sample host (use src/data/examples images/videos)`);
    if (/\/standards\//.test(rel) && /(StandardPage|PatternPage)\.tsx$/.test(name)) {
      if (!HAND_WRITTEN_SNIPPET_OK.has(name) && !/buildExampleSnippet\(/.test(source))
        failures.push(`${rel}: snippet must be generated with buildExampleSnippet() from the rendered props`);
      if (/\.mp4["'`]/.test(source) && !/mediaUrl\(/.test(source) && !/data\/examples\/videos/.test(source))
        failures.push(`${rel}: video must come from src/data/examples/videos (mediaUrl)`);
    }
    if (/src[\\/]data[\\/]/.test(rel) && /examples|placement|missing-dog|kennel/.test(name) && HARD_DATE.test(source))
      failures.push(`${rel}: hardcoded ISO date in example data (use daysAgoISO/daysFromNowISO)`);
  }
}

const assetDir = path.join(root, "src", "assets", "examples");
for (const f of fs.existsSync(assetDir) ? fs.readdirSync(assetDir) : []) {
  if (!/\.(webp|svg)$/.test(f)) failures.push(`src/assets/examples/${f}: examples images must be .webp or .svg`);
}

if (failures.length) {
  console.error(`check-standards-examples: ${failures.length} problem(s)\n- ${failures.join("\n- ")}`);
  console.error("See internal-tools/4leggedit-websites/docs/governance/standards-page-contract.md");
  process.exit(1);
}
console.log("check-standards-examples: standards examples OK");
